def solve(N: int, K: int, S: str) -> int:
    def count_sheets(i, j):
        count = 0
        for k in range(i + 1, j):
            if S[k] == ':':
                count += 1
        return count

    def can_attraction_be_positive(i, j):
        return K + 1 - abs(j - i) - count_sheets(i, j) > 0

    def can_attain(i, j):
        if S[i] == 'M' and S[j] == 'I':
            return can_attraction_be_positive(i, j)
        elif S[i] == 'I' and S[j] == 'M':
            return can_attraction_be_positive(j, i)
        return False

    max_magnets = 0
    for i in range(N):
        if S[i] == 'M':
            for j in range(i + 1, N):
                if S[j] == 'I' and can_attain(i, j):
                    max_magnets += 1
